# Normal production path: Streamlit Community Cloud installs these packages from
# requirements.txt before app.py starts. The lightweight fallback below only runs
# when a dependency file was not detected/installed, so a deployment does not fail
# with ModuleNotFoundError. When requirements.txt is present, this performs only
# quick import checks and does not run pip.
import streamlit as st

_RUNTIME_PACKAGES = Path(tempfile.gettempdir()) / "pt_bima_python_packages"
if str(_RUNTIME_PACKAGES) not in sys.path:
    sys.path.insert(0, str(_RUNTIME_PACKAGES))

_DEPENDENCIES = {
    "bcrypt": "bcrypt>=4.2,<5.0",
    "gspread": "gspread>=6.1,<7.0",
    "pandas": "pandas>=2.2,<3.0",
    "plotly": "plotly>=5.24,<7.0",
    "google.oauth2.service_account": "google-auth>=2.35,<3.0",
    "googleapiclient.discovery": "google-api-python-client>=2.147,<3.0",
    "reportlab": "reportlab>=4.2,<5.0",
    "fitz": "PyMuPDF>=1.24,<2.0",
    "qrcode": "qrcode[pil]>=7.4,<9.0",
}

def _ensure_dependencies_fallback() -> None:
    missing: list[str] = []
    for module_name, package_spec in _DEPENDENCIES.items():
        try:
            importlib.import_module(module_name)
        except ModuleNotFoundError:
            missing.append(package_spec)

    if not missing:
        return

    _RUNTIME_PACKAGES.mkdir(parents=True, exist_ok=True)
    command = [
        sys.executable,
        "-m",
        "pip",
        "install",
        "--quiet",
        "--disable-pip-version-check",
        "--no-warn-script-location",
        "--prefer-binary",
        "--target",
        str(_RUNTIME_PACKAGES),
        *missing,
    ]
    try:
        with st.spinner("Menyiapkan dependency aplikasi yang belum tersedia..."):
            subprocess.check_call(command)
        importlib.invalidate_caches()
    except Exception:
        st.error(
            "Dependency aplikasi belum tersedia. Pastikan file requirements.txt "
            "berada di root repository GitHub atau di folder yang sama dengan file utama aplikasi."
        )
        st.code("\n".join(missing), language="text")
        st.stop()

_ensure_dependencies_fallback()

