_RUNTIME_DIR = Path(tempfile.gettempdir()) / "pt_bima_master_material_runtime"

def _materialize_embedded_assets() -> None:
    image_dir = _RUNTIME_DIR / "assets" / "images"
    css_dir = _RUNTIME_DIR / "assets" / "css"
    image_dir.mkdir(parents=True, exist_ok=True)
    css_dir.mkdir(parents=True, exist_ok=True)
    for filename, encoded in _EMBEDDED_IMAGES.items():
        target = image_dir / filename
        raw = base64.b64decode(encoded)
        if not target.exists() or target.stat().st_size != len(raw):
            target.write_bytes(raw)
    css_target = css_dir / "style.css"
    if not css_target.exists() or css_target.read_text(encoding="utf-8") != _EMBEDDED_CSS:
        css_target.write_text(_EMBEDDED_CSS, encoding="utf-8")

_materialize_embedded_assets()


