def canonical_status(value: Any) -> str:
    """Normalize legacy/human-readable status values to the internal workflow constants.

    Google Sheets may contain rows created by older app versions using labels such
    as "Pending L1" instead of "PENDING_L1". Workqueue matching must remain
    reliable across those versions.
    """
    raw = str(value or "").strip()
    if not raw:
        return ""
    key = re.sub(r"[^A-Z0-9]+", "_", raw.upper()).strip("_")
    aliases = {
        "SUBMITTED": STATUS_SUBMITTED,
        "PENDING_L1": STATUS_PENDING_L1,
        "PENDING_APPROVAL_L1": STATUS_PENDING_L1,
        "PENDING_L2": STATUS_PENDING_L2,
        "PENDING_APPROVAL_L2": STATUS_PENDING_L2,
        "PENDING_L3": STATUS_PENDING_L3,
        "PENDING_APPROVAL_L3": STATUS_PENDING_L3,
        "PENDING_L4": STATUS_PENDING_L4,
        "PENDING_APPROVAL_L4": STATUS_PENDING_L4,
        "APPROVED_FINAL": STATUS_APPROVED_FINAL,
        "APPROVED": STATUS_APPROVED_FINAL,
        "FINAL_APPROVED": STATUS_APPROVED_FINAL,
        "REJECTED": STATUS_REJECTED,
        "REJECT": STATUS_REJECTED,
        "REVISION_REQUIRED": STATUS_REVISION,
        "REVISION": STATUS_REVISION,
        "PERLU_REVISI": STATUS_REVISION,
        "PARTIAL_FINAL": STATUS_PARTIAL_FINAL,
        "PARTIAL_REJECTED": STATUS_PARTIAL_REJECTED,
        "PARTIAL_REJECT": STATUS_PARTIAL_REJECTED,
    }
    return aliases.get(key, raw)


