# ============================== utils/helpers.py ==============================
INDONESIAN_MONTHS = {
    1: "Januari",
    2: "Februari",
    3: "Maret",
    4: "April",
    5: "Mei",
    6: "Juni",
    7: "Juli",
    8: "Agustus",
    9: "September",
    10: "Oktober",
    11: "November",
    12: "Desember",
}


def now_jakarta() -> datetime:
    return datetime.now(ZoneInfo(TIMEZONE))


def iso_now() -> str:
    return now_jakarta().isoformat(timespec="seconds")


def parse_datetime(value: Any) -> datetime | None:
    if value is None or str(value).strip() == "":
        return None
    raw = str(value).strip()
    try:
        dt = datetime.fromisoformat(raw.replace("Z", "+00:00"))
    except ValueError:
        dt = pd.to_datetime(raw, errors="coerce")
        if pd.isna(dt):
            return None
        dt = dt.to_pydatetime()
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=ZoneInfo(TIMEZONE))
    return dt.astimezone(ZoneInfo(TIMEZONE))


def format_date_id(value: Any) -> str:
    dt = parse_datetime(value)
    if not dt:
        return "-"
    return f"{dt.day:02d} {INDONESIAN_MONTHS[dt.month]} {dt.year}"


def format_datetime_id(value: Any) -> str:
    dt = parse_datetime(value)
    if not dt:
        return "-"
    return f"{dt.day:02d} {INDONESIAN_MONTHS[dt.month]} {dt.year} {dt:%H:%M} WIB"


def format_short_date(value: Any) -> str:
    dt = parse_datetime(value)
    if not dt:
        return "-"
    mon = INDONESIAN_MONTHS[dt.month][:3]
    return f"{dt.day:02d} {mon} {dt.year}"


def status_label(status: str | None) -> str:
    return STATUS_LABELS.get(str(status or "").upper(), str(status or "-").replace("_", " ").title())


def normalize_header(value: str) -> str:
    value = str(value or "").strip().lower()
    value = re.sub(r"[^a-z0-9]+", "_", value)
    return value.strip("_")


def first_nonempty(mapping: dict[str, Any], aliases: Iterable[str], default: Any = "") -> Any:
    normalized = {normalize_header(k): v for k, v in mapping.items()}
    for alias in aliases:
        value = normalized.get(normalize_header(alias))
        if value is not None and str(value).strip() != "":
            return value
    return default


def image_to_data_uri(path: Path) -> str:
    if not path.exists():
        return ""
    suffix = path.suffix.lower().lstrip(".") or "png"
    mime = "image/jpeg" if suffix in {"jpg", "jpeg"} else f"image/{suffix}"
    data = base64.b64encode(path.read_bytes()).decode("ascii")
    return f"data:{mime};base64,{data}"


def bytes_to_data_uri(data: bytes, mime: str) -> str:
    return f"data:{mime};base64,{base64.b64encode(data).decode('ascii')}"


def initials(name: str) -> str:
    words = [w for w in re.split(r"\s+", str(name).strip()) if w]
    if not words:
        return "U"
    if len(words) == 1:
        return words[0][0].upper()
    return (words[0][0] + words[-1][0]).upper()


def dataframe_to_csv_bytes(df: pd.DataFrame) -> bytes:
    return df.to_csv(index=False).encode("utf-8-sig")


def safe_text(value: Any, fallback: str = "-") -> str:
    text = str(value or "").strip()
    return text if text else fallback


def calculate_processing_days(created_at: Any, finished_at: Any | None = None) -> float | None:
    start = parse_datetime(created_at)
    end = parse_datetime(finished_at) if finished_at else now_jakarta()
    if not start or not end:
        return None
    seconds = max(0.0, (end - start).total_seconds())
    return round(seconds / 86400, 2)


def compact_number(value: float | int) -> str:
    try:
        num = float(value)
    except (TypeError, ValueError):
        return "0"
    if num.is_integer():
        return f"{int(num):,}".replace(",", ".")
    return f"{num:,.1f}".replace(",", "X").replace(".", ",").replace("X", ".")


def pdf_bytes_buffer() -> io.BytesIO:
    return io.BytesIO()


