# ============================== utils/validators.py ==============================
URL_PATTERN = re.compile(r"^https?://[^\s]+$", re.IGNORECASE)


def required(value: Any) -> bool:
    return value is not None and str(value).strip() != ""


def valid_url(value: str) -> bool:
    return bool(URL_PATTERN.match(str(value or "").strip()))


def validate_request_payload(payload: dict, items: list[dict]) -> list[str]:
    errors: list[str] = []
    for field, label in {
        "nama_pemohon": "Nama Pemohon",
        "tanggal_pengajuan": "Tanggal Pengajuan",
        "area": "Area",
        "site": "Site",
        "description": "Kebutuhan / Deskripsi",
        "profit_center": "Profit Center",
        "storage_location": "Storage Location",
        "valuation_class": "Valuation Class",
        "document_url": "URL Dokumen / Link Manual",
    }.items():
        if not required(payload.get(field)):
            errors.append(f"{label} wajib diisi.")

    if required(payload.get("document_url")) and not valid_url(str(payload["document_url"])):
        errors.append("URL Dokumen / Link Manual harus diawali http:// atau https://.")

    if not items:
        errors.append("Minimal satu item material harus ditambahkan.")
    for idx, item in enumerate(items, start=1):
        for field, label in {
            "material_name": "Nama Barang / Material Master",
            "brand": "Merk / Brand",
            "part_number": "Part Number",
            "material_type": "Material Type",
            "material_group": "Material Group",
            "uom": "UOM / Unit of Measure",
        }.items():
            if not required(item.get(field)):
                errors.append(f"Item {idx}: {label} wajib diisi.")
    return errors


def validate_password_change(current_password: str, new_password: str, confirm_password: str) -> list[str]:
    errors: list[str] = []
    if not current_password:
        errors.append("Password saat ini wajib diisi.")
    if len(new_password or "") < 8:
        errors.append("Password baru minimal 8 karakter.")
    if new_password != confirm_password:
        errors.append("Konfirmasi password baru tidak sama.")
    if current_password and new_password and current_password == new_password:
        errors.append("Password baru harus berbeda dari password saat ini.")
    return errors


# ============================== services/sheets_service.py ==============================
SHEETS_SCOPES = [
    "https://www.googleapis.com/auth/spreadsheets",
    "https://www.googleapis.com/auth/drive.file",
]


class SheetsServiceError(RuntimeError):
    """Raised when Google Sheets cannot satisfy an application operation."""


@st.cache_resource(show_spinner=False)
def get_gspread_client() -> gspread.Client:
    try:
        service_account_info = dict(st.secrets["gcp_service_account"])
    except Exception as exc:
        raise SheetsServiceError(
            "Credential Google Cloud belum tersedia. Tambahkan [gcp_service_account] pada Streamlit Secrets."
        ) from exc
    try:
        credentials = Credentials.from_service_account_info(service_account_info, scopes=SHEETS_SCOPES)
        return gspread.authorize(credentials)
    except Exception as exc:
        raise SheetsServiceError("Credential Google Cloud tidak valid atau tidak dapat digunakan.") from exc


@st.cache_resource(show_spinner=False)
def get_spreadsheet() -> gspread.Spreadsheet:
    try:
        return get_gspread_client().open_by_key(SPREADSHEET_ID)
    except gspread.SpreadsheetNotFound as exc:
        raise SheetsServiceError(
            "Spreadsheet tidak ditemukan atau belum dibagikan kepada service account."
        ) from exc
    except Exception as exc:
        raise SheetsServiceError("Koneksi ke spreadsheet gagal. Periksa Google Sheets API dan jaringan.") from exc


def _google_error_status(exc: Exception) -> int | None:
    response = getattr(exc, "response", None)
    status = getattr(response, "status_code", None)
    if status is None:
        status = getattr(response, "status", None)
    try:
        return int(status) if status is not None else None
    except Exception:
        return None


def _is_transient_google_error(exc: Exception) -> bool:
    status = _google_error_status(exc)
    if status in {429, 500, 502, 503, 504}:
        return True
    message = str(exc).lower()
    transient_markers = (
        "quota exceeded",
        "rate limit",
        "too many requests",
        "429",
        "backend error",
        "service unavailable",
        "internal error",
    )
    return any(marker in message for marker in transient_markers)


def _google_retry(operation, attempts: int = 4):
    last_exc = None
    for attempt in range(attempts):
        try:
            return operation()
        except Exception as exc:
            last_exc = exc
            if not _is_transient_google_error(exc) or attempt >= attempts - 1:
                raise
            time.sleep(0.7 * (2 ** attempt))
    if last_exc is not None:
        raise last_exc


@st.cache_resource(show_spinner=False)
def get_worksheet(sheet_name: str) -> gspread.Worksheet:
    try:
        return _google_retry(lambda: get_spreadsheet().worksheet(sheet_name))
    except gspread.WorksheetNotFound as exc:
        raise SheetsServiceError(f'Worksheet "{sheet_name}" tidak ditemukan.') from exc
    except SheetsServiceError:
        raise
    except Exception as exc:
        status = _google_error_status(exc)
        if status == 403:
            raise SheetsServiceError(
                f'Tidak memiliki izin untuk membuka worksheet "{sheet_name}". Pastikan service account diberi akses Editor.'
            ) from exc
        if status == 429 or _is_transient_google_error(exc):
            raise SheetsServiceError(
                f'Google Sheets sedang membatasi permintaan saat membuka worksheet "{sheet_name}". Coba ulang beberapa detik lagi.'
            ) from exc
        raise SheetsServiceError(f'Gagal membuka worksheet "{sheet_name}".') from exc


@st.cache_data(ttl=120, show_spinner=False)
def get_worksheet_titles_cached() -> tuple[str, ...]:
    try:
        worksheets = _google_retry(lambda: get_spreadsheet().worksheets())
        return tuple(str(ws.title).strip() for ws in worksheets)
    except SheetsServiceError:
        raise
    except Exception as exc:
        status = _google_error_status(exc)
        if status == 403:
            raise SheetsServiceError(
                "Service account dapat login, tetapi tidak memiliki izin yang cukup untuk membaca struktur spreadsheet."
            ) from exc
        if status == 429 or _is_transient_google_error(exc):
            raise SheetsServiceError(
                "Google Sheets API sedang terkena batas permintaan. Aplikasi akan mencoba ulang otomatis; bila masih muncul, tunggu beberapa detik lalu refresh."
            ) from exc
        raise SheetsServiceError("Gagal membaca daftar worksheet pada spreadsheet.") from exc


@st.cache_data(ttl=CACHE_TTL_SECONDS, show_spinner=False)
def get_sheet_records_cached(sheet_name: str) -> list[dict[str, Any]]:
    try:
        return _google_retry(lambda: get_worksheet(sheet_name).get_all_records(default_blank=""))
    except SheetsServiceError:
        raise
    except Exception as exc:
        status = _google_error_status(exc)
        if status == 429 or _is_transient_google_error(exc):
            raise SheetsServiceError(
                "Google Sheets sedang mencapai batas baca sementara. Tunggu beberapa detik lalu coba lagi."
            ) from exc
        raise SheetsServiceError(f'Gagal membaca data dari worksheet "{sheet_name}".') from exc


@st.cache_data(ttl=600, show_spinner=False)
def get_headers_cached(sheet_name: str) -> tuple[str, ...]:
    try:
        values = _google_retry(lambda: get_worksheet(sheet_name).row_values(1))
        return tuple(str(value).strip() for value in values)
    except SheetsServiceError:
        raise
    except Exception as exc:
        status = _google_error_status(exc)
        if status == 429 or _is_transient_google_error(exc):
            raise SheetsServiceError(
                f'Google Sheets sedang membatasi pembacaan header worksheet "{sheet_name}". Coba lagi beberapa detik.'
            ) from exc
        raise SheetsServiceError(f'Gagal membaca header worksheet "{sheet_name}".') from exc


def clear_data_cache(sheet_name: str | None = None) -> None:
    """Invalidate only the sheet that changed when Streamlit supports keyed clears.

    Clearing the entire cache after every Audit Log / Approval write caused the
    next rerun to re-read Data Permohonan, Data Approval, master data, etc. That
    amplified Google Sheets read traffic and could hit the per-minute quota.
    """
    if sheet_name:
        try:
            get_sheet_records_cached.clear(sheet_name)
            return
        except Exception:
            pass
    get_sheet_records_cached.clear()


def clear_header_cache() -> None:
    get_headers_cached.clear()


def clear_sheet_metadata_cache() -> None:
    get_worksheet_titles_cached.clear()
    get_worksheet.clear()
    get_headers_cached.clear()


def worksheet_exists(sheet_name: str) -> bool:
    try:
        target = str(sheet_name).strip()
        return target in set(get_worksheet_titles_cached())
    except SheetsServiceError:
        raise
    except Exception as exc:
        raise SheetsServiceError(f'Gagal memeriksa worksheet "{sheet_name}".') from exc


def read_records(sheet_name: str, fresh: bool = False) -> list[dict[str, Any]]:
    if fresh:
        try:
            return _google_retry(lambda: get_worksheet(sheet_name).get_all_records(default_blank=""))
        except Exception as exc:
            if isinstance(exc, SheetsServiceError):
                raise
            raise SheetsServiceError(f'Gagal membaca data terbaru dari worksheet "{sheet_name}".') from exc
    return get_sheet_records_cached(sheet_name)


def get_headers(sheet_name: str) -> list[str]:
    # Header worksheet berubah sangat jarang. Cache agar setiap append/update tidak
    # menghabiskan kuota Google Sheets hanya untuk membaca baris header yang sama.
    return list(get_headers_cached(sheet_name))


def _header_lookup(headers: Iterable[str]) -> dict[str, int]:
    return {normalize_header(header): idx for idx, header in enumerate(headers, start=1) if str(header).strip()}


def append_dict(sheet_name: str, data: dict[str, Any]) -> int:
    """Append a dict using the worksheet's existing header order.

    Returns the appended row number when Google returns an updated range.
    """
    ws = get_worksheet(sheet_name)
    headers = get_headers(sheet_name)
    if not headers:
        raise SheetsServiceError(
            f'Worksheet "{sheet_name}" belum memiliki header. Jalankan scripts/bootstrap_sheets.py terlebih dahulu.'
        )
    normalized_data = {normalize_header(k): v for k, v in data.items()}
    row = [normalized_data.get(normalize_header(header), "") for header in headers]
    try:
        result = _google_retry(lambda: ws.append_row(row, value_input_option="USER_ENTERED"))
        clear_data_cache(sheet_name)
    except Exception as exc:
        raise SheetsServiceError(f'Gagal menambahkan data ke worksheet "{sheet_name}".') from exc

    try:
        updated_range = result.get("updates", {}).get("updatedRange", "")
        # e.g. 'System Sequence'!A12:C12
        last = updated_range.split("!")[-1].split(":")[0]
        row_digits = "".join(ch for ch in last if ch.isdigit())
        return int(row_digits) if row_digits else 0
    except Exception:
        return 0


def update_rows_by_key(
    sheet_name: str,
    key_column: str,
    key_value: Any,
    updates: dict[str, Any],
) -> int:
    """Update every data row matching key_column=key_value.

    Useful for requests stored one-row-per-material item while workflow status is
    request-level and must be kept consistent across all rows.
    """
    ws = get_worksheet(sheet_name)
    values = _google_retry(lambda: ws.get_all_values())
    if not values:
        return 0
    headers = values[0]
    lookup = _header_lookup(headers)
    key_idx = lookup.get(normalize_header(key_column))
    if not key_idx:
        raise SheetsServiceError(f'Kolom kunci "{key_column}" tidak ditemukan di "{sheet_name}".')

    normalized_updates = {normalize_header(k): v for k, v in updates.items()}
    missing = [k for k in normalized_updates if k not in lookup]
    if missing:
        raise SheetsServiceError(
            f'Kolom {", ".join(missing)} tidak tersedia di worksheet "{sheet_name}".'
        )

    batch: list[dict[str, Any]] = []
    matched = 0
    for row_no, row in enumerate(values[1:], start=2):
        current = row[key_idx - 1] if len(row) >= key_idx else ""
        if str(current).strip() != str(key_value).strip():
            continue
        matched += 1
        for field, value in normalized_updates.items():
            col_no = lookup[field]
            batch.append({"range": rowcol_to_a1(row_no, col_no), "values": [[value]]})

    if not batch:
        return 0
    try:
        _google_retry(lambda: ws.batch_update(batch, value_input_option="USER_ENTERED"))
        clear_data_cache(sheet_name)
        return matched
    except Exception as exc:
        raise SheetsServiceError(f'Gagal memperbarui data pada worksheet "{sheet_name}".') from exc


_SCHEMA_MIGRATION_LOCK = threading.Lock()


def ensure_sheet_columns(sheet_name: str, required_columns: Iterable[str]) -> list[str]:
    """Append missing header columns safely and with minimal Google API writes.

    Older versions wrote every missing header using ``update_cell``. A schema
    upgrade with several new columns could therefore trigger write quota limits,
    and could also fail when the worksheet grid had fewer physical columns than
    the new schema. This implementation expands the grid once when required and
    writes the complete header row in a single request.
    """
    ws = get_worksheet(sheet_name)
    headers = get_headers(sheet_name)
    required = [str(c).strip() for c in required_columns if str(c).strip()]
    normalized = {normalize_header(h) for h in headers if str(h).strip()}
    missing = [column for column in required if normalize_header(column) not in normalized]
    if not missing:
        return headers

    # Multiple browser sessions can start at nearly the same time. Serialize the
    # migration inside the Streamlit process and re-read the header while holding
    # the lock so another session cannot append the same columns again.
    with _SCHEMA_MIGRATION_LOCK:
        try:
            fresh_headers = [str(value).strip() for value in _google_retry(lambda: ws.row_values(1), attempts=5)]
            fresh_normalized = {normalize_header(h) for h in fresh_headers if h}
            missing = [column for column in required if normalize_header(column) not in fresh_normalized]
            if not missing:
                clear_header_cache()
                return fresh_headers

            merged_headers = fresh_headers + missing
            target_cols = len(merged_headers)

            # Google Sheets rejects writes beyond the current grid size. Older
            # Data Dokumen sheets commonly had only 10 columns, while QR
            # verification expands the schema beyond that limit.
            if int(getattr(ws, "col_count", 0) or 0) < target_cols:
                _google_retry(lambda: ws.resize(cols=target_cols), attempts=5)

            end_cell = rowcol_to_a1(1, target_cols)
            _google_retry(
                lambda: ws.update(
                    [merged_headers],
                    f"A1:{end_cell}",
                    value_input_option="RAW",
                ),
                attempts=5,
            )

            clear_data_cache(sheet_name)
            clear_header_cache()
            return merged_headers
        except Exception as exc:
            status = _google_error_status(exc)
            if status == 403:
                raise SheetsServiceError(
                    f'Gagal memperbarui struktur worksheet "{sheet_name}" karena service account tidak memiliki akses Editor.'
                ) from exc
            if status == 429 or _is_transient_google_error(exc):
                raise SheetsServiceError(
                    f'Google Sheets sedang membatasi perubahan struktur worksheet "{sheet_name}". '
                    "Tunggu sekitar 60 detik lalu buka ulang aplikasi."
                ) from exc
            if status == 400:
                raise SheetsServiceError(
                    f'Struktur worksheet "{sheet_name}" belum dapat diperluas otomatis. '
                    "Pastikan worksheet tidak diproteksi dan service account memiliki akses Editor."
                ) from exc
            raise SheetsServiceError(f'Gagal menambahkan kolom baru pada worksheet "{sheet_name}".') from exc


def repair_request_item_numbers() -> int:
    """Backfill blank item_no values in Data Permohonan without changing request data.

    Earlier deployments could store multi-item rows before the item_no column was
    introduced. The approval UI needs a stable per-item key, so blanks are filled
    sequentially per request. Existing nonblank item numbers are preserved.
    """
    if not worksheet_exists(SHEET_REQUESTS):
        return 0
    ensure_sheet_columns(SHEET_REQUESTS, ["item_no"])
    ws = get_worksheet(SHEET_REQUESTS)
    values = _google_retry(lambda: ws.get_all_values())
    if len(values) < 2:
        return 0
    headers = values[0]
    lookup = _header_lookup(headers)
    req_col = lookup.get("request_id")
    item_col = lookup.get("item_no")
    if not req_col or not item_col:
        return 0

    used: dict[str, set[int]] = {}
    next_no: dict[str, int] = {}
    for row in values[1:]:
        rid = (row[req_col - 1] if len(row) >= req_col else "").strip()
        raw_no = (row[item_col - 1] if len(row) >= item_col else "").strip()
        if not rid:
            continue
        used.setdefault(rid, set())
        if raw_no:
            try:
                num = int(float(raw_no))
                used[rid].add(num)
            except Exception:
                pass
    for rid, nums in used.items():
        next_no[rid] = max(nums, default=0) + 1

    batch: list[dict[str, Any]] = []
    for row_no, row in enumerate(values[1:], start=2):
        rid = (row[req_col - 1] if len(row) >= req_col else "").strip()
        raw_no = (row[item_col - 1] if len(row) >= item_col else "").strip()
        if not rid or raw_no:
            continue
        candidate = next_no.get(rid, 1)
        while candidate in used.setdefault(rid, set()):
            candidate += 1
        used[rid].add(candidate)
        next_no[rid] = candidate + 1
        batch.append({"range": rowcol_to_a1(row_no, item_col), "values": [[candidate]]})

    if not batch:
        return 0
    try:
        _google_retry(lambda: ws.batch_update(batch, value_input_option="USER_ENTERED"))
        clear_data_cache(SHEET_REQUESTS)
        return len(batch)
    except Exception as exc:
        raise SheetsServiceError('Gagal memperbaiki nomor item pada worksheet "Data Permohonan".') from exc


def update_row_by_keys(
    sheet_name: str,
    key_values: dict[str, Any],
    updates: dict[str, Any],
) -> int:
    """Update rows matching all key/value pairs.

    Needed for item-level workflow because request_id alone identifies several
    material rows under one request.
    """
    ws = get_worksheet(sheet_name)
    values = _google_retry(lambda: ws.get_all_values())
    if not values:
        return 0
    headers = values[0]
    lookup = _header_lookup(headers)
    normalized_keys = {normalize_header(k): v for k, v in key_values.items()}
    normalized_updates = {normalize_header(k): v for k, v in updates.items()}

    missing_keys = [k for k in normalized_keys if k not in lookup]
    missing_updates = [k for k in normalized_updates if k not in lookup]
    if missing_keys or missing_updates:
        missing = missing_keys + missing_updates
        raise SheetsServiceError(f'Kolom {", ".join(missing)} tidak tersedia di worksheet "{sheet_name}".')

    batch: list[dict[str, Any]] = []
    matched = 0
    for row_no, row in enumerate(values[1:], start=2):
        is_match = True
        for field, expected in normalized_keys.items():
            col_no = lookup[field]
            current = row[col_no - 1] if len(row) >= col_no else ""
            if str(current).strip() != str(expected).strip():
                is_match = False
                break
        if not is_match:
            continue
        matched += 1
        for field, value in normalized_updates.items():
            batch.append({"range": rowcol_to_a1(row_no, lookup[field]), "values": [[value]]})

    if not batch:
        return 0
    try:
        _google_retry(lambda: ws.batch_update(batch, value_input_option="USER_ENTERED"))
        clear_data_cache(sheet_name)
        return matched
    except Exception as exc:
        raise SheetsServiceError(f'Gagal memperbarui data item pada worksheet "{sheet_name}".') from exc


def upsert_dict(sheet_name: str, key_column: str, key_value: Any, data: dict[str, Any]) -> str:
    ws = get_worksheet(sheet_name)
    values = _google_retry(lambda: ws.get_all_values())
    if not values:
        raise SheetsServiceError(f'Worksheet "{sheet_name}" belum memiliki header.')
    headers = values[0]
    lookup = _header_lookup(headers)
    key_idx = lookup.get(normalize_header(key_column))
    if not key_idx:
        raise SheetsServiceError(f'Kolom kunci "{key_column}" tidak ditemukan di "{sheet_name}".')

    target_row = 0
    for row_no, row in enumerate(values[1:], start=2):
        current = row[key_idx - 1] if len(row) >= key_idx else ""
        if str(current).strip() == str(key_value).strip():
            target_row = row_no
            break

    if not target_row:
        append_dict(sheet_name, data)
        return "inserted"

    normalized_data = {normalize_header(k): v for k, v in data.items()}
    batch: list[dict[str, Any]] = []
    for field, value in normalized_data.items():
        col_no = lookup.get(field)
        if col_no:
            batch.append({"range": rowcol_to_a1(target_row, col_no), "values": [[value]]})
    if not batch:
        return "unchanged"
    try:
        _google_retry(lambda: ws.batch_update(batch, value_input_option="USER_ENTERED"))
        clear_data_cache(sheet_name)
        return "updated"
    except Exception as exc:
        raise SheetsServiceError(f'Gagal memperbarui worksheet "{sheet_name}".') from exc


def update_single_cell_by_key(
    sheet_name: str,
    key_column: str,
    key_value: Any,
    target_column: str,
    value: Any,
) -> bool:
    return bool(update_rows_by_key(sheet_name, key_column, key_value, {target_column: value}))


def create_worksheet_if_missing(sheet_name: str, headers: list[str], rows: int = 1000) -> bool:
    """Create a missing worksheet without modifying existing worksheets."""
    if worksheet_exists(sheet_name):
        return False
    try:
        ws = _google_retry(
            lambda: get_spreadsheet().add_worksheet(
                title=sheet_name, rows=rows, cols=max(10, len(headers) + 2)
            )
        )
        _google_retry(lambda: ws.update([headers], "A1"))
        clear_data_cache(sheet_name)
        clear_sheet_metadata_cache()
        return True
    except Exception as exc:
        status = _google_error_status(exc)
        if status == 403:
            raise SheetsServiceError(
                f'Worksheet "{sheet_name}" belum ada dan service account tidak memiliki izin Editor untuk membuatnya.'
            ) from exc
        raise SheetsServiceError(f'Gagal membuat worksheet "{sheet_name}".') from exc


def append_dicts(sheet_name: str, rows_data: list[dict[str, Any]]) -> int:
    """Append multiple dictionaries in one Google Sheets request."""
    if not rows_data:
        return 0
    ws = get_worksheet(sheet_name)
    headers = get_headers(sheet_name)
    if not headers:
        raise SheetsServiceError(
            f'Worksheet "{sheet_name}" belum memiliki header. Jalankan scripts/bootstrap_sheets.py terlebih dahulu.'
        )
    rows: list[list[Any]] = []
    for data in rows_data:
        normalized_data = {normalize_header(k): v for k, v in data.items()}
        rows.append([normalized_data.get(normalize_header(header), "") for header in headers])
    try:
        _google_retry(lambda: ws.append_rows(rows, value_input_option="USER_ENTERED"))
        clear_data_cache(sheet_name)
        return len(rows)
    except Exception as exc:
        raise SheetsServiceError(f'Gagal menambahkan data ke worksheet "{sheet_name}".') from exc


