def log_event(
    username: str,
    role: str,
    activity: str,
    request_id: str = "",
    description: str = "",
    *,
    strict: bool = False,
) -> bool:
    try:
        if not worksheet_exists(SHEET_AUDIT):
            if strict:
                raise SheetsServiceError(f'Worksheet "{SHEET_AUDIT}" tidak ditemukan.')
            return False
        append_dict(
            SHEET_AUDIT,
            {
                "timestamp": iso_now(),
                "username": username,
                "role": role,
                "activity": activity,
                "request_id": request_id,
                "description": description,
            },
        )
        return True
    except Exception:
        if strict:
            raise
        return False


# ============================== services/auth_service.py ==============================
USER_ALIASES = {
    "username": ["username", "user name", "user", "id user"],
    "password": ["password", "kata sandi", "pass"],
    "nama": ["nama", "nama lengkap", "name"],
    "role": ["role", "peran", "kelompok", "level"],
    "jabatan": ["jabatan", "position", "title"],
    "area": ["area"],
    "site": ["site", "lokasi", "unit"],
    "email": ["email", "e-mail"],
    "no_hp": ["no hp", "nomor hp", "phone", "telepon"],
    "nomor_pegawai": ["nomor pegawai", "no pegawai", "nip", "employee id"],
    "status_akun": ["status akun", "status", "active", "aktif"],
}


def _canonical_user(record: dict[str, Any]) -> dict[str, str]:
    user = {key: str(first_nonempty(record, aliases, "")).strip() for key, aliases in USER_ALIASES.items()}
    user["role"] = normalize_role(user["role"])
    return user


def _password_matches(input_password: str, stored_password: str) -> bool:
    stored = str(stored_password or "")
    if stored.startswith(("$2a$", "$2b$", "$2y$")):
        try:
            return bcrypt.checkpw(input_password.encode("utf-8"), stored.encode("utf-8"))
        except ValueError:
            return False
    # Legacy compatibility for an existing sheet that still has plain-text
    # passwords. New password writes use bcrypt hashes.
    return hmac.compare_digest(input_password, stored)


def authenticate(username: str, password: str) -> dict[str, str] | None:
    username = str(username or "").strip()
    if not username or not password:
        return None
    records = read_records(SHEET_USERS, fresh=True)
    for record in records:
        user = _canonical_user(record)
        if user["username"].lower() != username.lower():
            continue
        if user["status_akun"] and user["status_akun"].strip().lower() in {"inactive", "nonaktif", "0", "false", "disabled"}:
            raise PermissionError("Akun pengguna tidak aktif. Hubungi administrator sistem.")
        if not _password_matches(password, user["password"]):
            return None
        if not user["role"]:
            raise SheetsServiceError("Role pengguna belum diatur pada Google Sheets.")
        return user
    return None


def get_user(username: str, fresh: bool = False) -> dict[str, str] | None:
    for record in read_records(SHEET_USERS, fresh=fresh):
        user = _canonical_user(record)
        if user["username"].lower() == str(username).strip().lower():
            return user
    return None


def verify_user_password(username: str, password: str) -> bool:
    user = get_user(username, fresh=True)
    return bool(user and _password_matches(password, user["password"]))


def hash_password(password: str) -> str:
    return bcrypt.hashpw(password.encode("utf-8"), bcrypt.gensalt(rounds=12)).decode("utf-8")


def change_password(username: str, current_password: str, new_password: str) -> None:
    if not verify_user_password(username, current_password):
        raise ValueError("Password saat ini tidak sesuai.")
    headers = get_headers(SHEET_USERS)
    normalized_headers = {str(h).strip(): normalize_header(h) for h in headers}
    username_aliases = {normalize_header(v) for v in USER_ALIASES["username"]}
    password_aliases = {normalize_header(v) for v in USER_ALIASES["password"]}
    username_header = next((h for h, n in normalized_headers.items() if n in username_aliases), "username")
    password_header = next((h for h, n in normalized_headers.items() if n in password_aliases), "password")
    updated = update_rows_by_key(
        SHEET_USERS,
        username_header,
        username,
        {password_header: hash_password(new_password)},
    )
    if not updated:
        raise SheetsServiceError("Pengguna tidak ditemukan saat memperbarui password.")


# ============================== services/profile_service.py ==============================
class ProfileService:
    def get_profile(self, user: dict[str, Any]) -> dict[str, Any]:
        profile = dict(user)
        if not worksheet_exists(SHEET_PROFILE):
            return profile
        username = str(user.get("username", "")).lower()
        for raw in read_records(SHEET_PROFILE):
            row = {normalize_header(k): v for k, v in raw.items()}
            if str(row.get("username", "")).lower() == username:
                for key, value in row.items():
                    if value not in (None, ""):
                        profile[key] = value
                break
        return profile

    def save_preferences(self, user: dict[str, Any], bahasa: str, tampilan: str) -> None:
        if not worksheet_exists(SHEET_PROFILE):
            return
        data = {
            "username": user.get("username", ""),
            "nama": user.get("nama", ""),
            "email": user.get("email", ""),
            "no_hp": user.get("no_hp", ""),
            "nomor_pegawai": user.get("nomor_pegawai", ""),
            "jabatan": user.get("jabatan", ""),
            "role": user.get("role", ""),
            "area": user.get("area", ""),
            "site": user.get("site", ""),
            "bahasa": bahasa,
            "tampilan": tampilan,
            "updated_at": iso_now(),
        }
        upsert_dict(SHEET_PROFILE, "username", user.get("username", ""), data)


