# ============================== components/charts.py ==============================
STATUS_COLORS = {
    STATUS_APPROVED_FINAL: "#1267B2",
    STATUS_PENDING_L1: "#4EA6ED",
    STATUS_PENDING_L2: "#F5A623",
    STATUS_PENDING_L3: "#F6C85F",
    STATUS_PENDING_L4: "#9A87F4",
    STATUS_REJECTED: "#F05B61",
}


def _layout(fig: go.Figure, height: int = 255) -> go.Figure:
    fig.update_layout(
        height=height,
        margin=dict(l=10, r=10, t=12, b=18),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="Inter, Segoe UI, Arial", color="#425E76", size=10),
        hoverlabel=dict(font_size=10, bgcolor="#FFFFFF", bordercolor="#DDE7F0"),
        showlegend=True,
    )
    return fig


def workflow_donut(status_counts: dict[str, int]) -> go.Figure:
    keys = [STATUS_APPROVED_FINAL, STATUS_PENDING_L1, STATUS_PENDING_L2, STATUS_PENDING_L3, STATUS_PENDING_L4, STATUS_REJECTED]
    actual_total = sum(int(status_counts.get(k, 0) or 0) for k in keys)
    labels = [status_label(k) for k in keys if status_counts.get(k, 0)]
    values = [status_counts.get(k, 0) for k in keys if status_counts.get(k, 0)]
    colors = [STATUS_COLORS[k] for k in keys if status_counts.get(k, 0)]
    if not values:
        labels, values, colors = ["Belum ada data"], [1], ["#E9EFF5"]
    fig = go.Figure(
        data=[go.Pie(
            labels=labels,
            values=values,
            hole=0.62,
            marker=dict(colors=colors, line=dict(color="#FFFFFF", width=1)),
            textinfo="none",
            sort=False,
            hovertemplate="%{label}: %{value}<extra></extra>",
        )]
    )
    fig.update_layout(
        legend=dict(orientation="v", y=0.5, x=1.02, font=dict(size=9), itemwidth=30),
        annotations=[dict(
            text=f"<b>{actual_total}</b><br><span style='font-size:10px;color:#73879A'>Total Request</span>",
            x=0.36, y=0.5, showarrow=False, font=dict(size=22, color="#153B5A"), align="center"
        )],
    )
    return _layout(fig, height=250)


def area_bar(area_counts: dict[str, int]) -> go.Figure:
    pairs = sorted(area_counts.items(), key=lambda x: x[1], reverse=True)[:6]
    x = [p[0] for p in pairs]
    y = [p[1] for p in pairs]
    palette = ["#1267B2", "#4C9EE5", "#75B6EC", "#A5D0F4", "#C3DDF3", "#D5E7F5"]
    fig = go.Figure(go.Bar(
        x=x,
        y=y,
        marker_color=palette[:len(x)],
        width=0.48,
        text=y,
        textposition="outside",
        textfont=dict(size=10, color="#294A64"),
        cliponaxis=False,
        hovertemplate="%{x}: %{y}<extra></extra>",
    ))
    fig.update_layout(showlegend=False)
    fig.update_xaxes(showgrid=False, tickfont=dict(size=9), linecolor="#E7EEF4")
    fig.update_yaxes(showgrid=True, gridcolor="#EEF3F7", zeroline=False, tickfont=dict(size=9), rangemode="tozero")
    return _layout(fig, height=250)


def material_group_bar(group_counts: dict[str, int]) -> go.Figure:
    pairs = sorted(group_counts.items(), key=lambda x: x[1], reverse=False)[-6:]
    y = [p[0] for p in pairs]
    x = [p[1] for p in pairs]
    palette = ["#C5E0F5", "#A8D1F1", "#7FBAEA", "#5AA4DF", "#3188CE", "#1267B2"][-len(x):]
    fig = go.Figure(go.Bar(
        x=x,
        y=y,
        orientation="h",
        marker_color=palette,
        text=x,
        textposition="outside",
        textfont=dict(size=9, color="#294A64"),
        cliponaxis=False,
        hovertemplate="%{y}: %{x}<extra></extra>",
    ))
    fig.update_layout(showlegend=False)
    fig.update_xaxes(showgrid=False, zeroline=False, showticklabels=False)
    fig.update_yaxes(showgrid=False, tickfont=dict(size=9), automargin=True)
    return _layout(fig, height=245)


