def render_header(user: dict, notification_count: int = 0) -> bool:
    count = min(int(notification_count or 0), 99)
    count_html = f'<span class="count">{count}</span>' if count else ""
    outer = st.container(border=False)
    with outer:
        st.markdown('<span class="bima-header-marker"></span>', unsafe_allow_html=True)
        cols = st.columns([7.7, 0.48, 1.65, 0.42], gap="small", vertical_alignment="center")
        with cols[0]:
            st.markdown('<div class="bima-header-context">Sistem Master Material SAP</div>', unsafe_allow_html=True)
        with cols[1]:
            st.markdown(f'<div class="bima-notification">{BELL_SVG}{count_html}</div>', unsafe_allow_html=True)
        with cols[2]:
            st.markdown(
                f'''<div class="bima-header-user">
                      <div class="bima-avatar">{html.escape(initials(str(user.get('nama') or user.get('username') or 'U')))}</div>
                      <div class="bima-user-meta">
                        <strong>{html.escape(str(user.get('nama') or user.get('username') or 'Pengguna'))}</strong>
                        <span>{html.escape(str(user.get('role') or user.get('jabatan') or ''))}</span>
                      </div>
                    </div>''',
                unsafe_allow_html=True,
            )
        with cols[3]:
            logout_clicked = False
            with st.popover("⌄", use_container_width=True):
                st.markdown(f"**{html.escape(str(user.get('nama') or user.get('username') or 'Pengguna'))}**")
                st.caption(str(user.get("role") or ""))
                if user.get("email"):
                    st.caption(str(user.get("email")))
                if user.get("site"):
                    st.caption(str(user.get("site")))
                try:
                    logout_clicked = st.button("Logout", icon=":material/logout:", key="header_logout", use_container_width=True)
                except TypeError:
                    logout_clicked = st.button("Logout", key="header_logout", use_container_width=True)
    return logout_clicked

