def _profit_center_from_site(site: str) -> str:
    """Return Profit Center otomatis berdasarkan kode Site terpilih."""
    if not site:
        return ""
    site_code = str(site).split(" - ", 1)[0].strip()
    return PROFIT_CENTER_BY_SITE_CODE.get(site_code, "")

def render_request_form_page(user: dict, request_service: RequestService, approval_service: ApprovalService) -> None:
    if normalize_role(str(user.get("role", ""))) != ROLE_USER:
        st.error("Halaman Form Permintaan Material hanya dapat diakses oleh Pemohon.")
        return

    if st.session_state.pop("request_reset_pending", False):
        _reset_request_widgets()
