def render_approval_page(user: dict, request_service: RequestService, approval_service: ApprovalService) -> None:
    role = normalize_role(str(user.get("role", "")))
    if role not in APPROVER_ROLES:
        st.error("Akun ini tidak memiliki akses ke Approval Workqueue.")
        return

    flash = st.session_state.pop("approval_flash", "")
    if flash:
        st.success(flash)

    expected_status = ROLE_EXPECTED_STATUS[role]
    level = ROLE_LEVEL[role]
    role_meta = {
        ROLE_L1: (
            "Modul Approval Admin Peralatan Area (L1)",
            "Menampilkan permohonan baru yang membutuhkan persetujuan Admin Peralatan Area (L1).",
        ),
        ROLE_L2: (
            "Modul Approval Manper Area (L2)",
            "Menampilkan permohonan yang telah disetujui L1 untuk verifikasi Manper Area (L2).",
        ),
        ROLE_L3: (
            "Modul Approval Manager Akuntansi (L3)",
            "Menampilkan permohonan yang telah disetujui L2 untuk verifikasi Manager Akuntansi (L3).",
        ),
        ROLE_L4: (
            "Modul Approval Manager Persediaan (L4)",
            "Menampilkan permohonan yang telah disetujui L3 untuk verifikasi akhir Manager Persediaan (L4).",
        ),
    }
    role_title, role_desc = role_meta[role]

    head_left, head_right = st.columns([6.2, 1.15], gap="small", vertical_alignment="bottom")
    with head_left:
        page_heading("Approval Workqueue", f"Item material yang saat ini menunggu persetujuan {level}")
    with head_right:
        if st.button("Refresh Data", key="approval_refresh_data", use_container_width=True):
            clear_data_cache()
            st.session_state.pop("approval_selected_request", None)
            st.session_state.pop("approval_selected_item_no", None)
            st.rerun()

    page_intro_banner(
        "Approval Workspace",
        "Verifikasi berjenjang mulai dari Admin Peralatan Area (L1), Manper Area (L2), Manager Akuntansi (L3), hingga Manager Persediaan (L4). Keputusan berlaku per item material.",
    )
    st.markdown(
        f'<div class="bima-role-hero"><div><span class="bima-role-eyebrow">WORKQUEUE {html.escape(level)}</span>'
        f'<strong>{html.escape(role_title)}</strong><small>{html.escape(role_desc)}</small></div>'
        f'<div class="bima-role-status">{status_badge_html(expected_status)}</div></div>',
        unsafe_allow_html=True,
    )

    queue = approval_service.get_workqueue(user)
    st.markdown('<div class="bima-vgap-12"></div>', unsafe_allow_html=True)
    with st.container(border=True):
        st.markdown('<span class="bima-filter-marker bima-filter-card-marker"></span>', unsafe_allow_html=True)
        st.markdown(
            '<div class="bima-filter-title"><strong>Pending Review</strong><span>Cari item aktif pada antrean approval level ini.</span></div>',
            unsafe_allow_html=True,
        )
        f1, f2, f3 = st.columns([2.2, 1.2, 1.2], gap="small")
        with f1:
            search = st.text_input("Search", key="approval_search", placeholder="REQ ID, pemohon, nama material, atau part number")
        with f2:
            areas = ["Semua"] + sorted(v for v in queue.get("area", pd.Series(dtype=str)).astype(str).unique() if v) if not queue.empty else ["Semua"]
            area = st.selectbox("Area", areas, key="approval_area")
        with f3:
            groups = ["Semua"] + sorted(v for v in queue.get("material_group", pd.Series(dtype=str)).astype(str).unique() if v) if not queue.empty else ["Semua"]
            group = st.selectbox("Material Group", groups, key="approval_group")

    filtered = queue.copy()
    if not filtered.empty and search.strip():
        q = search.strip().lower()
        filtered = filtered[
            filtered["request_id"].astype(str).str.lower().str.contains(q, na=False)
            | filtered["nama_pemohon"].astype(str).str.lower().str.contains(q, na=False)
            | filtered["material_name"].astype(str).str.lower().str.contains(q, na=False)
            | filtered["part_number"].astype(str).str.lower().str.contains(q, na=False)
            | filtered["brand"].astype(str).str.lower().str.contains(q, na=False)
        ]
    if not filtered.empty and area != "Semua":
        filtered = filtered[filtered["area"].astype(str) == area]
    if not filtered.empty and group != "Semua":
        filtered = filtered[filtered["material_group"].astype(str) == group]

    st.markdown('<div class="bima-vgap-12"></div>', unsafe_allow_html=True)
    with st.container(border=True):
        st.markdown('<span class="bima-list-panel-marker"></span>', unsafe_allow_html=True)
        section_heading("Approval Queue", f"{len(filtered)} item menunggu review {level}")
        selected = render_approval_item_table(filtered.reset_index(drop=True), "approval_queue", role)
    if selected:
        st.session_state["approval_selected_request"] = selected[0]
        st.session_state["approval_selected_item_no"] = selected[1]

    selected_request = st.session_state.get("approval_selected_request", "")
    selected_item_no = st.session_state.get("approval_selected_item_no", "")
    if not selected_request or str(selected_item_no).strip() == "":
        return

    item_row = request_service.get_item(selected_request, selected_item_no)
    if not item_row:
        st.warning("Item material yang dipilih tidak ditemukan.")
        st.session_state.pop("approval_selected_request", None)
        st.session_state.pop("approval_selected_item_no", None)
        return

    history = approval_service.get_history(selected_request, selected_item_no)
    current_status = canonical_status(item_row.get("status", ""))

    st.markdown('<div class="bima-vgap-16"></div>', unsafe_allow_html=True)
    st.markdown(
        f'<div class="bima-card"><div class="bima-card-title">{html.escape(selected_request)} · Item #{html.escape(str(selected_item_no))}</div>'
        f'<div class="bima-card-subtitle">{html.escape(safe_text(item_row.get("material_name")))} · {status_badge_html(current_status)}</div></div>',
        unsafe_allow_html=True,
    )
    st.markdown('<div class="bima-vgap-12"></div>', unsafe_allow_html=True)

    left, right = st.columns([2.15, 1], gap="medium")
    with left:
        with st.container(border=True):
            st.markdown('<span class="bima-detail-panel-marker"></span>', unsafe_allow_html=True)
            section_heading(f"Informasi Review {level}", "Informasi ditampilkan sesuai kebutuhan approval pada level aktif.")
            render_approval_review_information(role, item_row, history)
            if str(item_row.get("document_url", "")).startswith("http"):
                st.write("")
                st.link_button("Buka Dokumen / Manual", str(item_row.get("document_url")), use_container_width=True)

    with right:
        with st.container(border=True):
            st.markdown('<span class="bima-approval-panel-marker"></span>', unsafe_allow_html=True)
            section_heading("Keputusan Approval")
            st.markdown(
                f'<div class="bima-approval-current"><span>Status Item #{html.escape(str(selected_item_no))}</span>{status_badge_html(current_status)}</div>',
                unsafe_allow_html=True,
            )
            if current_status != expected_status:
                st.warning("Item ini sudah berubah status dan tidak lagi dapat diproses pada level akun Anda.")
                return

            recommendation = ""
            material_reference = _approval_material_reference(item_row)
            character_count = _approval_material_character_count(item_row)
            needs_recommendation = role == ROLE_L1 and character_count > 40
            if role == ROLE_L1:
                if needs_recommendation:
                    st.warning(
                        f"Gabungan Brand; Nama Barang; Part Number berjumlah {character_count} karakter. "
                        "Karena melebihi 40 karakter, Rekomendasi Nama Material wajib diisi sebelum Approve."
                    )
                    recommendation = st.text_input(
                        "Rekomendasi Nama Material *",
                        key=f"approval_recommendation_{selected_request}_{selected_item_no}",
                        max_chars=40,
                        placeholder="Maksimal 40 karakter",
                    )
                    st.caption(f"{len(recommendation)}/40 karakter")
                else:
                    st.success(
                        f"Jumlah karakter {character_count} ≤ 40. Rekomendasi Nama Material tidak diperlukan."
                    )

            note = st.text_area(
                "Catatan Approver",
                key=f"approval_note_{selected_request}_{selected_item_no}",
                placeholder="Catatan opsional untuk approve dan wajib untuk reject.",
                height=120,
            )
            st.caption("Reject merupakan keputusan final untuk item tersebut dan tidak dikembalikan ke Pemohon untuk diajukan ulang.")

            if "approval_processing" not in st.session_state:
                st.session_state["approval_processing"] = False
            approve_disabled = st.session_state["approval_processing"] or (needs_recommendation and not recommendation.strip())
            approve_clicked = st.button(
                "Setujui (Approve)",
                type="primary",
                key=f"approve_{selected_request}_{selected_item_no}",
                use_container_width=True,
                disabled=approve_disabled,
            )
            reject_clicked = st.button(
                "Tolak (Reject)",
                key=f"reject_{selected_request}_{selected_item_no}",
                use_container_width=True,
                disabled=st.session_state["approval_processing"],
            )

    if approve_clicked or reject_clicked:
        st.session_state["approval_processing"] = True
        try:
            with st.spinner("Memvalidasi item dan menyimpan keputusan approval..."):
                if approve_clicked:
                    next_status = approval_service.approve(
                        selected_request,
                        user,
                        note,
                        item_no=selected_item_no,
                        recommended_material_name=recommendation,
                    )
                    st.session_state["approval_flash"] = (
                        f"{selected_request} Item #{selected_item_no} berhasil disetujui. "
                        f"Status baru: {status_label(next_status)}."
                    )
                else:
                    approval_service.reject(
                        selected_request,
                        user,
                        note,
                        item_no=selected_item_no,
                        recommended_material_name=recommendation,
                    )
                    st.session_state["approval_flash"] = f"{selected_request} Item #{selected_item_no} telah ditolak secara final."
            st.session_state.pop("approval_selected_request", None)
            st.session_state.pop("approval_selected_item_no", None)
            st.rerun()
        except (SheetsServiceError, ValueError, PermissionError) as exc:
            st.error(str(exc))
        except Exception as exc:
            if _google_error_status(exc) == 429 or _is_transient_google_error(exc):
                st.error("Google Sheets sedang mencapai batas permintaan sementara. Tunggu sekitar 30-60 detik, lalu klik Refresh Data dan ulangi aksi.")
            else:
                st.error(str(exc))
        finally:
            st.session_state["approval_processing"] = False

# ============================== pages_app/request_history.py ==============================
def render_request_history_page(user: dict, request_service: RequestService, approval_service: ApprovalService) -> None:
    if normalize_role(str(user.get("role", ""))) != ROLE_USER:
        st.error("Riwayat Permohonan hanya tersedia untuk Pemohon.")
        return

    head_left, head_right = st.columns([5.4, 1.35], gap="small", vertical_alignment="bottom")
    with head_left:
        page_heading("Riwayat Permohonan", "Daftar seluruh permintaan master material yang telah Anda ajukan")
    with head_right:
        if st.button("Buat Permintaan Baru", key="history_new_request", type="primary", use_container_width=True):
            st.session_state["current_page"] = PAGE_REQUEST_FORM
            st.rerun()

    page_intro_banner(
        "Riwayat Permohonan",
        "Pantau seluruh request yang pernah diajukan, termasuk item yang masih diproses, telah selesai, atau telah ditolak sebagai keputusan final approval.",
    )
    df = request_service.get_scoped_headers(user)
    status_series = df["status"].astype(str) if not df.empty else pd.Series(dtype=str)

    with st.container(border=True):
        st.markdown('<span class="bima-filter-marker bima-filter-card-marker"></span>', unsafe_allow_html=True)
        st.markdown('<div class="bima-filter-title"><strong>Filter Riwayat</strong><span>Saring request berdasarkan periode, status, site, atau nama material.</span></div>', unsafe_allow_html=True)
        f1, f2, f3, f4 = st.columns([1.5, 1.15, 1.2, 1.8], gap="small")
        with f1:
            period = st.date_input("Periode", value=(date.today() - timedelta(days=90), date.today()), key="history_period")
        with f2:
            status_options = ["Semua"] + sorted(v for v in status_series.unique() if v)
            status_filter = st.selectbox("Status", status_options, key="history_status")
        with f3:
            site_options = ["Semua"] + (sorted(v for v in df["site"].astype(str).unique() if v) if not df.empty else [])
            site_filter = st.selectbox("Area / Site", site_options, key="history_site")
        with f4:
            material_search = st.text_input("Nama Material", key="history_material", placeholder="Cari nama material atau REQ ID")

    st.markdown('<div class="bima-vgap-12"></div>', unsafe_allow_html=True)
    if df.empty:
        pending_request_count = rejected_request_count = approved_request_count = 0
    else:
        pending_counts = pd.to_numeric(df.get("pending_item_count", 0), errors="coerce").fillna(0)
        rejected_counts = pd.to_numeric(df.get("rejected_item_count", 0), errors="coerce").fillna(0)
        pending_request_count = int((pending_counts > 0).sum())
        rejected_request_count = int((rejected_counts > 0).sum())
        approved_request_count = int((status_series == STATUS_APPROVED_FINAL).sum())
    render_four_metrics([
        ("Total Permintaan", str(len(df)), "Seluruh request Anda", COLOR_PRIMARY),
        ("Pending Approval", str(pending_request_count), "Request dengan item masih diproses", "#F2B544"),
        ("Approved Final", str(approved_request_count), "Seluruh item selesai sampai L4", COLOR_SUCCESS),
        ("Rejected", str(rejected_request_count), "Request yang memiliki item ditolak", COLOR_DANGER),
    ])

    filtered = df.copy()
    if not filtered.empty:
        dates = pd.to_datetime(filtered["created_at"], errors="coerce").dt.date
        if isinstance(period, tuple) and len(period) == 2:
            filtered = filtered[(dates >= period[0]) & (dates <= period[1])]
        if status_filter != "Semua":
            filtered = filtered[filtered["status"].astype(str) == status_filter]
        if site_filter != "Semua":
            filtered = filtered[filtered["site"].astype(str) == site_filter]
        if material_search.strip():
            q = material_search.strip().lower()
            filtered = filtered[
                filtered["request_id"].astype(str).str.lower().str.contains(q, na=False)
                | filtered["material_name_display"].astype(str).str.lower().str.contains(q, na=False)
            ]

    st.markdown('<div class="bima-vgap-16"></div>', unsafe_allow_html=True)
    with st.container(border=True):
        st.markdown('<span class="bima-list-panel-marker"></span>', unsafe_allow_html=True)
        section_heading("Daftar Riwayat Permohonan", f"{len(filtered)} request ditemukan")
        selected = render_request_table(filtered.reset_index(drop=True), "history_table")
    if selected:
        st.session_state["history_selected_request"] = selected
    selected = st.session_state.get("history_selected_request", "")
    if selected:
        detail = request_service.get_request(selected)
        if detail:
            st.markdown('<div class="bima-vgap-16"></div>', unsafe_allow_html=True)
            with st.container(border=True):
                section_heading("Detail Permohonan")
                render_request_detail(detail, approval_service.get_history(selected))

            rejected_items = detail.items[
                detail.items["status"].map(canonical_status) == STATUS_REJECTED
            ].copy() if "status" in detail.items.columns else pd.DataFrame()

            if not rejected_items.empty:
                st.markdown('<div class="bima-vgap-16"></div>', unsafe_allow_html=True)
                with st.container(border=True):
                    section_heading(
                        "Item Rejected",
                        "Item yang ditolak merupakan keputusan final pada workflow dan tidak dikembalikan ke Pemohon untuk pengajuan ulang.",
                    )
                    for _, rejected_row in rejected_items.iterrows():
                        item_no = safe_text(rejected_row.get("item_no"))
                        reason = safe_text(rejected_row.get("rejection_note")) or "Tidak ada catatan penolakan."
                        r1, r2, r3 = st.columns([0.8, 2.4, 2.2], gap="small", vertical_alignment="center")
                        with r1:
                            st.markdown(f"**Item #{html.escape(item_no)}**")
                        with r2:
                            st.markdown(f"**{html.escape(safe_text(rejected_row.get('material_name')))}**")
                            st.caption(f"{safe_text(rejected_row.get('brand'))} · {safe_text(rejected_row.get('part_number'))}")
                        with r3:
                            st.markdown(status_badge_html(STATUS_REJECTED), unsafe_allow_html=True)
                            st.caption(f"Alasan: {reason}")

# ============================== pages_app/documents.py ==============================
def _render_pdf_preview(pdf_data: bytes, filename: str) -> None:
    """Render PDF pages as PNG images so preview works reliably on Streamlit Cloud.

    Native browser PDF plugins frequently refuse data: URLs inside the sandboxed
    iframe used by Streamlit components. Rasterising the generated PDF server-side
    avoids that browser/plugin limitation while the original PDF bytes are still
    used unchanged by the download button.
    """
    try:
        doc = fitz.open(stream=pdf_data, filetype="pdf")
        page_count = max(int(doc.page_count), 1)
        st.markdown(
            f'<div class="bima-pdf-toolbar"><span>{html.escape(filename)}</span>'
            f'<span>{page_count} halaman &nbsp;&nbsp; Preview</span></div>',
            unsafe_allow_html=True,
        )
        with st.container(border=True):
            for page_index in range(doc.page_count):
                page = doc.load_page(page_index)
                # 1.6x is crisp enough for desktop preview without making the app heavy.
                pixmap = page.get_pixmap(matrix=fitz.Matrix(1.6, 1.6), alpha=False)
                png_bytes = pixmap.tobytes("png")
                if page_count > 1:
                    st.caption(f"Halaman {page_index + 1} dari {page_count}")
                st.image(png_bytes, use_container_width=True)
                if page_index < page_count - 1:
                    st.markdown('<div style="height:10px;background:#EEF2F6;margin:4px -8px 12px -8px"></div>', unsafe_allow_html=True)
        doc.close()
        return
    except Exception:
        # Fallback: create a Blob URL instead of a data: PDF URL. Some browsers
        # allow the native PDF viewer through Blob even when direct data URLs fail.
        encoded = base64.b64encode(pdf_data).decode("ascii")
        safe_name = html.escape(filename)
        components.html(
            f"""
            <div style="height:720px;background:#eef2f6;border:1px solid #d6e1ea;overflow:hidden;">
              <iframe id="pdfPreviewFrame" title="{safe_name}" style="width:100%;height:100%;border:0;background:white;"></iframe>
            </div>
            <script>
              (function() {{
                const b64 = `{encoded}`;
                const binary = atob(b64);
                const bytes = new Uint8Array(binary.length);
                for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
                const blob = new Blob([bytes], {{type: 'application/pdf'}});
                const url = URL.createObjectURL(blob);
                document.getElementById('pdfPreviewFrame').src = url;
                window.addEventListener('beforeunload', () => URL.revokeObjectURL(url));
              }})();
            </script>
            """,
            height=725,
            scrolling=False,
        )


def render_documents_page(user: dict, request_service: RequestService, approval_service: ApprovalService) -> None:
    page_heading("Dokumen Persetujuan", "Lihat dan unduh dokumen keputusan approval master material")
    page_intro_banner(
        "Arsip Dokumen Persetujuan",
        "Pilih Request ID untuk melihat dokumen keputusan akhir. Item yang disetujui ditulis Approved Final dan item yang ditolak ditulis Rejected tanpa dikembalikan ke Pemohon.",
    )
    approved = request_service.get_scoped_headers(user)
    if not approved.empty:
        terminal_statuses = {STATUS_APPROVED_FINAL, STATUS_PARTIAL_FINAL, STATUS_REJECTED}
        approved = approved[approved["status"].astype(str).isin(terminal_statuses)].reset_index(drop=True)

    if approved.empty:
        st.info("Belum ada dokumen keputusan final. Dokumen tersedia setelah seluruh item pada Request ID selesai dengan status Approved Final dan/atau Rejected.")
        return

    left, center, right = st.columns([2.25, 5.3, 2.15], gap="medium")

    with left:
        with st.container(border=True):
            st.markdown('<span class="bima-document-list-marker"></span>', unsafe_allow_html=True)
            search = st.text_input("Cari dokumen", key="document_search", placeholder="Nomor request / nama material")
            scoped = approved.copy()
            if search.strip():
                q = search.strip().lower()
                scoped = scoped[
                    scoped["request_id"].astype(str).str.lower().str.contains(q, na=False)
                    | scoped["nama_pemohon"].astype(str).str.lower().str.contains(q, na=False)
                    | scoped["material_name_display"].astype(str).str.lower().str.contains(q, na=False)
                ].reset_index(drop=True)
            section_heading("Daftar Dokumen", "Request dengan keputusan akhir Approved Final dan/atau Rejected")
            if scoped.empty:
                st.markdown('<div class="bima-empty">Dokumen tidak ditemukan.</div>', unsafe_allow_html=True)
                return
            options = scoped["request_id"].astype(str).tolist()
            labels = {
                str(row["request_id"]): f"{row['request_id']}  ·  {row.get('material_name_display', '')}"
                for _, row in scoped.iterrows()
            }
            selected = st.radio(
                "Pilih request",
                options,
                format_func=lambda x: labels.get(x, x),
                key="document_selected",
                label_visibility="collapsed",
            )

    detail = request_service.get_request(selected)
    history = approval_service.get_history(selected)
    if not detail:
        st.error("Request tidak ditemukan.")
        return

    terminal_items = detail.items[
        detail.items["status"].map(canonical_status).isin([STATUS_APPROVED_FINAL, STATUS_REJECTED])
    ].copy().reset_index(drop=True)
    if terminal_items.empty or len(terminal_items) != len(detail.items):
        st.info("Dokumen final belum tersedia karena masih ada item yang berada dalam proses approval.")
        return
    pdf_header = dict(detail.header)
    pdf_header["status"] = aggregate_item_status(terminal_items)
    pdf_header["material_name"] = terminal_items.iloc[0].get("material_name", "")
    pdf_detail = RequestDetail(header=pdf_header, items=terminal_items)
    pdf_history = history.copy()

    try:
        with st.spinner("Membuat preview dan QR verifikasi dokumen..."):
            verification = prepare_document_verification(
                pdf_detail,
                pdf_history,
                generated_by=str(user.get("username", "")),
            )
            pdf_data = generate_approval_pdf(pdf_detail, pdf_history, verification=verification)
    except (PDFGenerationError, SheetsServiceError) as exc:
        st.error(str(exc))
        return

    with center:
        with st.container(border=True):
            st.markdown('<span class="bima-document-preview-marker"></span>', unsafe_allow_html=True)
            _render_pdf_preview(pdf_data, f"{selected}_Dokumen_Persetujuan.pdf")

    with right:
        downloaded = st.download_button(
            "Download PDF",
            data=pdf_data,
            file_name=f"{selected}_Dokumen_Persetujuan.pdf",
            mime="application/pdf",
            type="primary",
            use_container_width=True,
        )
        if downloaded:
            record_generation(selected, str(user.get("username", "")))
            log_event(
                str(user.get("username", "")),
                str(user.get("role", "")),
                "DOWNLOAD_DOCUMENT",
                selected,
                "Mengunduh dokumen persetujuan PDF.",
            )
        st.write("")
        with st.container(border=True):
            st.markdown('<span class="bima-document-info-marker"></span>', unsafe_allow_html=True)
            section_heading("Informasi Dokumen")
            h = detail.header
            st.markdown(
                f'''
                <div class="document-info-list">
                  <div><span>Nomor Request</span><strong>{html.escape(safe_text(h.get('request_id')))}</strong></div>
                  <div><span>ID Dokumen</span><strong>{html.escape(safe_text(verification.get('document_id')))}</strong></div>
                  <div><span>Versi</span><strong>V{html.escape(safe_text(verification.get('document_version')))}</strong></div>
                  <div><span>Nama Material</span><strong>{html.escape(safe_text(h.get('material_name')))}</strong></div>
                  <div><span>Tanggal Pengajuan</span><strong>{html.escape(format_date_id(h.get('created_at')))}</strong></div>
                  <div><span>Pemohon</span><strong>{html.escape(safe_text(h.get('nama_pemohon')))}</strong></div>
                  <div><span>Status</span>{status_badge_html(str(h.get('status','')))}</div>
                  <div><span>Verifikasi QR</span><strong style="color:#118959">ACTIVE</strong></div>
                </div>
                ''',
                unsafe_allow_html=True,
            )
            st.write("")
            section_heading("QR Keaslian")
            st.image(verification["qr_png"], width=150)
            st.caption("Scan QR pada PDF atau QR di atas untuk membuka halaman verifikasi keaslian dokumen.")
            if str(verification.get("verification_url", "")).startswith("http"):
                st.link_button("Buka Halaman Verifikasi", str(verification["verification_url"]), use_container_width=True)


