def render_profile_page(
    user: dict,
    request_service: RequestService,
    approval_service: ApprovalService,
    profile_service: ProfileService,
) -> None:
    flash = st.session_state.pop("profile_flash", "")
    if flash:
        st.success(flash)
    profile = profile_service.get_profile(user)
    role = normalize_role(str(user.get("role", "")))

    page_heading("Profile", "Informasi akun Anda pada Sistem Master Material SAP")
    page_intro_banner(
        "Informasi Akun",
        "Kelola informasi pengguna, keamanan akun, bahasa, tampilan, dan lihat ringkasan aktivitas sesuai peran Anda di sistem.",
    )
    left, right = st.columns([1.08, 1], gap="medium")
    with left:
        with st.container(border=True):
            st.markdown('<span class="bima-profile-info-marker"></span>', unsafe_allow_html=True)
            section_heading("Informasi Pengguna")
            st.markdown(
                f"""
                <div class="profile-hero">
                  <div class="profile-avatar">{html.escape(initials(str(profile.get('nama') or profile.get('username') or 'U')))}</div>
                  <div><h3>{html.escape(safe_text(profile.get('nama')))}</h3><p>{html.escape(safe_text(profile.get('role')))} · {html.escape(safe_text(profile.get('jabatan')))}</p></div>
                </div>
                """,
                unsafe_allow_html=True,
            )
            _profile_kv(profile)

    with right:
        with st.container(border=True):
            st.markdown('<span class="bima-profile-settings-marker"></span>', unsafe_allow_html=True)
            section_heading("Pengaturan Akun")
            with st.expander("Ubah Password", expanded=False):
                current = st.text_input("Password saat ini", type="password", key="profile_current_password")
                new = st.text_input("Password baru", type="password", key="profile_new_password")
                confirm = st.text_input("Konfirmasi password baru", type="password", key="profile_confirm_password")
                if st.button("Simpan Password", type="primary", key="profile_save_password", use_container_width=True):
                    errors = validate_password_change(current, new, confirm)
                    if errors:
                        for err in errors:
                            st.error(err)
                    else:
                        try:
                            with st.spinner("Memperbarui password..."):
                                change_password(str(user.get("username", "")), current, new)
                            log_event(str(user.get("username", "")), role, "CHANGE_PASSWORD", "", "Password akun diperbarui.")
                            st.session_state["profile_flash"] = "Password berhasil diperbarui."
                            st.rerun()
                        except Exception as exc:
                            st.error(str(exc))

            bahasa_options = ["Bahasa Indonesia", "English"]
            current_lang = str(profile.get("bahasa", "Bahasa Indonesia"))
            bahasa_index = bahasa_options.index(current_lang) if current_lang in bahasa_options else 0
            bahasa = st.selectbox("Bahasa", bahasa_options, index=bahasa_index, key="profile_language")
            display_options = ["Terang", "Ikuti sistem"]
            current_display = str(profile.get("tampilan", "Terang"))
            display_index = display_options.index(current_display) if current_display in display_options else 0
            tampilan = st.selectbox("Tampilan", display_options, index=display_index, key="profile_display")
            if st.button("Simpan Pengaturan", key="profile_save_preferences", use_container_width=True):
                profile_service.save_preferences(user, bahasa, tampilan)
                st.session_state["profile_flash"] = "Pengaturan akun berhasil disimpan."
                st.rerun()

    st.write("")
    with st.container(border=True):
        st.markdown('<span class="bima-profile-stats-marker"></span>', unsafe_allow_html=True)
        section_heading("Ringkasan Aktivitas Anda")
        if role == ROLE_USER:
            df = request_service.get_scoped_headers(user)
            statuses = df["status"].astype(str) if not df.empty else []
            total = len(df)
            pending = int(statuses.str.startswith("PENDING_").sum()) if hasattr(statuses, "str") else 0
            approved = int((statuses == STATUS_APPROVED_FINAL).sum()) if hasattr(statuses, "sum") else 0
            rejected = int((statuses == STATUS_REJECTED).sum()) if hasattr(statuses, "sum") else 0
            render_four_metrics(
                [
                    ("Total Permintaan", str(total), "Request yang Anda ajukan", COLOR_PRIMARY),
                    ("Pending Approval", str(pending), "Sedang diproses", "#D89A1D"),
                    ("Approved", str(approved), "Approved Final", COLOR_SUCCESS),
                    ("Rejected", str(rejected), "Permintaan ditolak", COLOR_DANGER),
                ]
            )
        elif role in APPROVER_ROLES:
            stats = approval_service.get_role_stats(user)
            level = ROLE_LEVEL[role]
            render_four_metrics(
                [
                    (f"Total Masuk {level}", str(stats["total_in"]), "Pernah atau sedang masuk antrean", COLOR_PRIMARY),
                    (f"Menunggu Approval {level}", str(stats["waiting"]), "Workqueue aktif", "#D89A1D"),
                    (f"Approved {level}", str(stats["approved"]), "Disetujui pada level ini", COLOR_SUCCESS),
                    (f"Rejected {level}", str(stats["rejected"]), "Ditolak pada level ini", COLOR_DANGER),
                ]
            )


def _profile_kv(profile: dict) -> None:
    rows = [
        ("Email", profile.get("email")),
        ("Nomor HP", profile.get("no_hp")),
        ("Jabatan", profile.get("jabatan")),
        ("Area", profile.get("area")),
        ("Site", profile.get("site")),
        ("Nomor Pegawai", profile.get("nomor_pegawai")),
    ]
    body = "".join(
        f'<div class="k">{html.escape(label)}</div><div class="v">{html.escape(safe_text(value))}</div>'
        for label, value in rows
    )
    st.markdown(f'<div class="profile-kv">{body}</div>', unsafe_allow_html=True)


