def _render_login() -> None:
    bg = image_to_data_uri(LOGIN_BG)
    danantara = image_to_data_uri(DANANTARA_LOGO)
    pelindo = image_to_data_uri(PELINDO_BIMA_LOGO)
    st.markdown(
        f"""
        <style>
          [data-testid="stSidebar"] {{ display:none !important; }}
          [data-testid="stMainBlockContainer"] {{ padding:0 !important; max-width:100% !important; margin:0 !important; }}
          [data-testid="stAppViewContainer"] {{ background-image:linear-gradient(90deg,rgba(239,248,254,.18),rgba(244,250,254,.08)),url('{bg}') !important; background-size:cover !important; background-position:center center !important; background-repeat:no-repeat !important; min-height:100vh !important; }}
          .login-logos {{ left:5vw !important; right:5vw !important; top:4.5vh !important; }}
          .login-logos img:first-child {{ width:126px !important; max-height:40px !important; }}
          .login-logos img:last-child {{ width:136px !important; max-height:43px !important; }}
          .login-side-copy {{ left:5.2vw !important; top:43vh !important; font-size:10px !important; letter-spacing:.12em !important; color:#2B638F !important; }}
          .login-footer-copy {{ left:5.2vw !important; bottom:4.2vh !important; font-size:9px !important; color:#638197 !important; }}
          [data-testid="stForm"] {{ width:100% !important; max-width:390px !important; margin:0 auto !important; border:1px solid rgba(218,230,240,.96) !important; border-radius:12px !important; padding:24px 26px 20px !important; background:rgba(255,255,255,.965) !important; box-shadow:0 16px 38px rgba(34,78,111,.14) !important; backdrop-filter:blur(4px) !important; }}
          .login-card-title {{ margin-bottom:16px !important; }}
          .login-card-title .eyebrow {{ font-size:10px !important; color:#8191A0 !important; letter-spacing:.09em !important; }}
          .login-card-title h1 {{ font-size:22px !important; line-height:1.15 !important; color:#173D5B !important; margin:6px 0 2px !important; }}
          .login-card-title strong {{ font-size:14px !important; color:#0066B3 !important; }}
          .login-card-title p {{ max-width:315px !important; margin:8px auto 0 !important; font-size:10.5px !important; line-height:1.45 !important; color:#8495A5 !important; }}
          [data-testid="stForm"] label p {{ font-size:11.5px !important; font-weight:600 !important; color:#314F67 !important; }}
          [data-testid="stForm"] input {{ min-height:40px !important; border:1px solid #D9E2EC !important; border-radius:6px !important; font-size:12px !important; box-shadow:none !important; }}
          [data-testid="stFormSubmitButton"] button {{ min-height:40px !important; border-radius:6px !important; background:#0066B3 !important; border-color:#0066B3 !important; font-size:12px !important; font-weight:650 !important; box-shadow:none !important; }}
          .login-corporate-note {{ margin-top:13px !important; padding-top:11px !important; font-size:9.5px !important; color:#8D9AA7 !important; }}
          @media (max-width:768px) {{ .login-side-copy,.login-footer-copy {{ display:none !important; }} .login-logos {{ top:3vh !important; }} }}
        </style>
        <div class="login-logos">
          <img src="{danantara}" alt="Danantara Indonesia">
          <img src="{pelindo}" alt="Pelindo PT BIMA">
        </div>
        <div class="login-side-copy">INTEGRATED MARITIME SOLUTIONS<br>FOR A SUSTAINABLE INDONESIA</div>
        <div class="login-footer-copy"><strong>PT BIMA</strong><br>Integrated Maritime Solutions<br>Sistem Master Material SAP</div>
        """,
        unsafe_allow_html=True,
    )

    st.markdown('<div style="height:18vh"></div>', unsafe_allow_html=True)
    left, center, right = st.columns([1.25, 0.76, 1.25], gap="large")
    with center:
        with st.form("login_form", clear_on_submit=False):
            st.markdown(
                """
                <div class="login-card-title">
                  <div class="eyebrow">SELAMAT DATANG DI</div>
                  <h1>Sistem Master Material</h1>
                  <strong>PT BIMA</strong>
                  <p>Gunakan username dan password akun Anda untuk mengakses sistem.</p>
                </div>
                """,
                unsafe_allow_html=True,
            )
            username = st.text_input("Username", placeholder="Masukkan username", autocomplete="username")
            password = st.text_input("Password", type="password", placeholder="Masukkan password", autocomplete="current-password")
            submitted = st.form_submit_button("MASUK", use_container_width=True)
            st.markdown('<div class="login-corporate-note">Akses sistem disesuaikan otomatis berdasarkan role akun.</div>', unsafe_allow_html=True)
        if submitted:
            if not username.strip() or not password:
                st.error("Username dan password wajib diisi.")
                return
            try:
                with st.spinner("Memverifikasi akun dan menghubungkan Google Sheets..."):
                    user = authenticate(username, password)
                if not user:
                    st.error("Username atau password tidak sesuai.")
                    return
                _set_authenticated_user(user)
                log_event(user["username"], user["role"], "LOGIN", "", "Login berhasil.")
                st.rerun()
            except PermissionError as exc:
                st.error(str(exc))
            except SheetsServiceError as exc:
                st.error(str(exc))
            except Exception:
                st.error("Login gagal diproses. Periksa koneksi dan konfigurasi sistem.")

def _set_authenticated_user(user: dict) -> None:
    st.session_state["authenticated"] = True
    st.session_state["logged_in"] = True
    for key in ["username", "nama", "role", "jabatan", "area", "site", "email", "no_hp", "nomor_pegawai"]:
        st.session_state[key] = str(user.get(key, ""))
    st.session_state["current_page"] = PAGE_DASHBOARD


def _current_user() -> dict:
    return {
        key: st.session_state.get(key, "")
        for key in ["username", "nama", "role", "jabatan", "area", "site", "email", "no_hp", "nomor_pegawai"]
    }


def _logout(user: dict) -> None:
    log_event(str(user.get("username", "")), str(user.get("role", "")), "LOGOUT", "", "Logout dari sistem.")
    for key in list(st.session_state.keys()):
        del st.session_state[key]
    st.rerun()


def _render_app() -> None:
    _inject_logged_in_css()
    user = _current_user()
    request_service = RequestService()
    approval_service = ApprovalService(request_service)
    profile_service = ProfileService()

    if not st.session_state.get("worksheets_checked", False):
        with st.spinner("Menyiapkan struktur data aplikasi..."):
            # Fetch worksheet metadata once. The previous implementation checked
            # every sheet with a separate API call, which could trigger Google
            # Sheets read-quota errors after several Streamlit reruns.
            existing_titles = set(get_worksheet_titles_cached())
            created_any = False
            for _sheet_name, _headers in SHEET_SCHEMAS.items():
                if _sheet_name == SHEET_USERS:
                    continue
                if _sheet_name not in existing_titles:
                    try:
                        ws = _google_retry(
                            lambda name=_sheet_name, hdrs=_headers: get_spreadsheet().add_worksheet(
                                title=name, rows=1000, cols=max(10, len(hdrs) + 2)
                            )
                        )
                        _google_retry(lambda ws=ws, hdrs=_headers: ws.update([hdrs], "A1"))
                        existing_titles.add(_sheet_name)
                        created_any = True
                    except Exception as exc:
                        status = _google_error_status(exc)
                        if status == 403:
                            raise SheetsServiceError(
                                f'Worksheet "{_sheet_name}" belum ada dan service account tidak memiliki akses Editor untuk membuatnya.'
                            ) from exc
                        raise SheetsServiceError(f'Gagal membuat worksheet "{_sheet_name}".') from exc
            if created_any:
                clear_sheet_metadata_cache()
                clear_data_cache()

            if SHEET_REQUESTS in existing_titles:
                ensure_sheet_columns(SHEET_REQUESTS, REQUEST_HEADERS)
                repair_request_item_numbers()
            if SHEET_APPROVALS in existing_titles:
                ensure_sheet_columns(SHEET_APPROVALS, APPROVAL_HEADERS)
            if SHEET_DOCUMENTS in existing_titles:
                ensure_sheet_columns(SHEET_DOCUMENTS, DOCUMENT_HEADERS)
        st.session_state["worksheets_checked"] = True

    current_page = str(st.session_state.get("current_page", PAGE_DASHBOARD))
    if not page_allowed(str(user.get("role", "")), current_page):
        current_page = PAGE_DASHBOARD
        st.session_state["current_page"] = PAGE_DASHBOARD

    new_page = render_sidebar(user, current_page)
    if new_page != current_page:
        if page_allowed(str(user.get("role", "")), new_page):
            st.session_state["current_page"] = new_page
            st.rerun()
        st.error("Anda tidak memiliki akses ke halaman tersebut.")
        return

    try:
        notification_count = request_service.notification_count(user)
    except Exception:
        notification_count = 0
    if render_header(user, notification_count):
        _logout(user)

    try:
        page = str(st.session_state.get("current_page", PAGE_DASHBOARD))
        if not page_allowed(str(user.get("role", "")), page):
            raise PermissionError("Anda tidak memiliki akses ke halaman tersebut.")
        if page == PAGE_DASHBOARD:
            render_dashboard_page(user, request_service, approval_service)
        elif page == PAGE_REQUEST_FORM:
            render_request_form_page(user, request_service, approval_service)
        elif page == PAGE_APPROVAL:
            render_approval_page(user, request_service, approval_service)
        elif page == PAGE_HISTORY:
            render_request_history_page(user, request_service, approval_service)
        elif page == PAGE_DOCUMENTS:
            render_documents_page(user, request_service, approval_service)
        elif page == PAGE_PROFILE:
            render_profile_page(user, request_service, approval_service, profile_service)
        else:
            st.session_state["current_page"] = PAGE_DASHBOARD
            st.rerun()
    except PermissionError as exc:
        st.error(str(exc))
    except SheetsServiceError as exc:
        st.error(str(exc))
        st.info("Periksa nama worksheet, akses service account, Google Sheets API, dan struktur header pada spreadsheet.")
    except Exception as exc:
        st.error("Halaman gagal dimuat karena terjadi kesalahan aplikasi.")
        with st.expander("Detail teknis"):
            st.code(str(exc))


_init_session()
_inject_base_css()
_verify_request = _query_param_value("verify")
_verify_version = _query_param_value("v")
_verify_token = _query_param_value("token")
if _verify_request:
    _render_public_verification_page(_verify_request, _verify_version, _verify_token)
elif not st.session_state.get("authenticated", False):
    _render_login()
else:
    _render_app()
